// Package asterisk generates Asterisk configuration from the database and talks to Asterisk over AMI.
//
// The static files in /etc/asterisk (shipped by the kiestoon package) include the generated files
// from <DataDir>/pbx with #tryinclude. Generation is deterministic: the same data gives the same
// files, so Kiestoon only reloads the Asterisk modules whose files changed.
package asterisk

import (
	"fmt"
	"sort"
	"strings"

	"github.com/rhisijmuiden/kiestoon/server/internal/pbx"
)

// Options are the parts of the configuration that do not come from the phone system tables.
type Options struct {
	AMIUser   string
	AMISecret string
	TLSCert   string
	TLSKey    string
	// MailFrom is the sender address of voicemail e-mails.
	MailFrom string
	// MailCmd is the program app_voicemail pipes e-mails into.
	MailCmd string
	// Organization is shown as the sender name of voicemail e-mails.
	Organization string
}

// Files maps a file name in the pbx directory to its contents.
type Files map[string]string

// Generate builds all generated configuration files.
func Generate(s *pbx.Snapshot, o Options) Files {
	return Files{
		"pjsip.conf":         genPJSIP(s, o),
		"extensions.conf":    genDialplan(s),
		"voicemail.conf":     genVoicemail(s, o),
		"manager_users.conf": genManager(o),
		"rtp.conf":           genRTP(s),
	}
}

const header = "; Generated by Kiestoon from its database. Do not edit: changes are overwritten.\n\n"

// esc protects a value in an Asterisk configuration file. Validation already rejects most
// special characters; this is a second line of defence.
func esc(v string) string {
	v = strings.NewReplacer("\n", "", "\r", "", ";", `\;`).Replace(v)
	return v
}

type w struct{ b strings.Builder }

func (x *w) f(format string, a ...any) { fmt.Fprintf(&x.b, format, a...); x.b.WriteByte('\n') }
func (x *w) nl()                       { x.b.WriteByte('\n') }

func codecLines(x *w, codecs string) {
	x.f("disallow=all")
	x.f("allow=%s", esc(codecs))
}

func genPJSIP(s *pbx.Snapshot, o Options) string {
	st := s.Settings
	var x w
	x.b.WriteString(header)
	x.f("[global]")
	x.f("type=global")
	x.f("user_agent=Kiestoon PBX")
	x.f("endpoint_identifier_order=ip,username,anonymous")
	x.f("keep_alive_interval=90")
	x.nl()

	nat := func() {
		for _, n := range st.LocalNets {
			x.f("local_net=%s", esc(n))
		}
		if st.ExternalAddress != "" {
			x.f("external_media_address=%s", esc(st.ExternalAddress))
			x.f("external_signaling_address=%s", esc(st.ExternalAddress))
		}
	}
	for _, t := range []struct{ name, proto string }{{"transport-udp", "udp"}, {"transport-tcp", "tcp"}} {
		x.f("[%s]", t.name)
		x.f("type=transport")
		x.f("protocol=%s", t.proto)
		x.f("bind=0.0.0.0:%d", st.SIPPort)
		x.f("tos=cs3")
		x.f("cos=3")
		nat()
		x.nl()
	}
	if o.TLSCert != "" {
		x.f("[transport-tls]")
		x.f("type=transport")
		x.f("protocol=tls")
		x.f("bind=0.0.0.0:%d", st.TLSPort)
		x.f("cert_file=%s", esc(o.TLSCert))
		x.f("priv_key_file=%s", esc(o.TLSKey))
		x.f("method=tlsv1_2")
		x.f("verify_client=no")
		x.f("verify_server=no")
		x.f("tos=cs3")
		x.f("cos=3")
		nat()
		x.nl()
	}

	// Internal extensions
	for _, e := range s.Extensions {
		if !e.Enabled {
			continue
		}
		x.f("; ---- extension %s: %s", e.Number, esc(e.Name))
		x.f("[%s]", e.Number)
		x.f("type=endpoint")
		x.f("context=kiestoon-internal")
		codecLines(&x, st.Codecs)
		x.f("auth=%s", e.Number)
		x.f("aors=%s", e.Number)
		x.f(`callerid="%s" <%s>`, esc(strings.ReplaceAll(e.Name, `"`, "")), e.Number)
		if e.Voicemail {
			x.f("mailboxes=%s@default", e.Number)
		}
		x.f("direct_media=no")
		x.f("rtp_symmetric=yes")
		x.f("force_rport=yes")
		x.f("rewrite_contact=yes")
		x.f("dtmf_mode=rfc4733")
		x.f("send_pai=yes")
		x.f("device_state_busy_at=0")
		x.f("tos_audio=ef")
		x.f("cos_audio=5")
		x.f("language=%s", st.Language)
		if e.SRTP {
			x.f("media_encryption=sdes")
			x.f("media_encryption_optimistic=no")
		}
		x.f("set_var=KT_EXT=%s", e.Number)
		if e.OutboundCID != "" {
			x.f("set_var=KT_OUTCID=%s", esc(e.OutboundCID))
		}
		x.nl()
		x.f("[%s]", e.Number)
		x.f("type=auth")
		x.f("auth_type=userpass")
		x.f("username=%s", e.Number)
		x.f("password=%s", esc(e.SIPSecret))
		x.nl()
		x.f("[%s]", e.Number)
		x.f("type=aor")
		x.f("max_contacts=%d", e.MaxContacts)
		x.f("remove_existing=yes")
		x.f("qualify_frequency=60")
		x.nl()
	}

	// Trunks
	for _, t := range s.Trunks {
		if !t.Enabled {
			continue
		}
		ep := t.Endpoint()
		transport := "transport-" + t.Transport
		hostport := fmt.Sprintf("%s:%d", t.Host, t.Port)
		uriSuffix := ""
		if t.Transport != "udp" {
			uriSuffix = ";transport=" + t.Transport
		}
		x.f("; ---- trunk %d: %s", t.ID, esc(t.Name))
		authUser := t.AuthUsername
		if authUser == "" {
			authUser = t.Username
		}
		if t.AuthMode == "register" {
			x.f("[%s-auth]", ep)
			x.f("type=auth")
			x.f("auth_type=userpass")
			x.f("username=%s", esc(authUser))
			x.f("password=%s", esc(t.Secret))
			x.nl()
			x.f("[%s]", ep)
			x.f("type=registration")
			x.f("transport=%s", transport)
			x.f("outbound_auth=%s-auth", ep)
			x.f("server_uri=sip:%s%s", hostport, uriSuffix)
			x.f("client_uri=sip:%s@%s%s", esc(t.Username), hostport, uriSuffix)
			x.f("contact_user=%s", esc(t.Username))
			x.f("retry_interval=60")
			x.f("forbidden_retry_interval=300")
			x.f("fatal_retry_interval=300")
			x.f("max_retries=10000")
			x.f("expiration=300")
			x.f("line=yes")
			x.f("endpoint=%s", ep)
			x.nl()
		}
		x.f("[%s]", ep)
		x.f("type=aor")
		x.f("contact=sip:%s%s", hostport, uriSuffix)
		x.f("qualify_frequency=60")
		x.nl()
		x.f("[%s]", ep)
		x.f("type=endpoint")
		x.f("transport=%s", transport)
		x.f("context=kiestoon-from-trunk")
		codecLines(&x, t.Codecs)
		x.f("aors=%s", ep)
		if t.AuthMode == "register" {
			x.f("outbound_auth=%s-auth", ep)
		}
		fromUser := t.FromUser
		if fromUser == "" && t.AuthMode == "register" {
			fromUser = t.Username
		}
		if fromUser != "" {
			x.f("from_user=%s", esc(fromUser))
		}
		fromDomain := t.FromDomain
		if fromDomain == "" && t.AuthMode == "register" {
			fromDomain = t.Host
		}
		if fromDomain != "" {
			x.f("from_domain=%s", esc(fromDomain))
		}
		x.f("direct_media=no")
		x.f("rtp_symmetric=yes")
		x.f("force_rport=yes")
		x.f("rewrite_contact=yes")
		x.f("dtmf_mode=rfc4733")
		x.f("send_pai=yes")
		x.f("send_rpid=yes")
		x.f("trust_id_inbound=yes")
		x.f("tos_audio=ef")
		x.f("cos_audio=5")
		x.f("language=%s", st.Language)
		if t.SRTP {
			x.f("media_encryption=sdes")
		}
		x.f("set_var=KT_TRUNK=%d", t.ID)
		x.f("set_var=KT_DIDSRC=%s", t.DIDSource)
		x.nl()
		matches := []string{t.Host}
		for _, ip := range strings.Split(t.MatchIPs, ",") {
			if ip != "" {
				matches = append(matches, ip)
			}
		}
		x.f("[%s]", ep)
		x.f("type=identify")
		x.f("endpoint=%s", ep)
		for _, m := range matches {
			x.f("match=%s", esc(m))
		}
		x.nl()
	}
	return x.b.String()
}

func genRTP(s *pbx.Snapshot) string {
	var x w
	x.b.WriteString(header)
	x.f("[general]")
	x.f("rtpstart=%d", s.Settings.RTPStart)
	x.f("rtpend=%d", s.Settings.RTPEnd)
	x.f("strictrtp=seqno")
	x.f("icesupport=no")
	return x.b.String()
}

func genManager(o Options) string {
	var x w
	x.b.WriteString(header)
	if o.AMISecret == "" {
		return x.b.String()
	}
	x.f("[%s]", o.AMIUser)
	x.f("secret=%s", esc(o.AMISecret))
	x.f("deny=0.0.0.0/0.0.0.0")
	x.f("permit=127.0.0.1/255.255.255.255")
	x.f("read=system,call,log,agent,user,config,dtmf,reporting,cdr,dialplan")
	x.f("write=system,call,agent,user,config,command,reporting,originate")
	x.f("writetimeout=5000")
	return x.b.String()
}

// vmText holds the voicemail e-mail texts. app_voicemail fills in the ${VM_...} variables.
var vmText = map[string][2]string{
	"en": {
		"New voicemail from ${VM_CALLERID} (${VM_DUR})",
		`Hello ${VM_NAME},\n\nYou have a new voicemail message of ${VM_DUR} in mailbox ${VM_MAILBOX}.\n\nFrom: ${VM_CALLERID}\nReceived: ${VM_DATE}\n\nThe message is attached to this e-mail.\n\n-- \nKiestoon`,
	},
	"nl": {
		"Nieuwe voicemail van ${VM_CALLERID} (${VM_DUR})",
		`Hallo ${VM_NAME},\n\nEr staat een nieuw voicemailbericht van ${VM_DUR} in voicemailbox ${VM_MAILBOX}.\n\nVan: ${VM_CALLERID}\nOntvangen: ${VM_DATE}\n\nHet bericht zit als bijlage bij deze e-mail.\n\n-- \nKiestoon`,
	},
}

func genVoicemail(s *pbx.Snapshot, o Options) string {
	var x w
	x.b.WriteString(header)
	text := vmText[s.Settings.Language]
	if text[0] == "" {
		text = vmText["en"]
	}
	x.f("[general]")
	x.f("format=wav")
	x.f("attach=yes")
	x.f("maxmsg=100")
	x.f("maxsecs=300")
	x.f("minsecs=2")
	x.f("maxlogins=3")
	x.f("review=no")
	x.f("operator=no")
	x.f("sendvoicemail=no")
	x.f("charset=UTF-8")
	if o.MailFrom != "" {
		x.f("serveremail=%s", esc(o.MailFrom))
	}
	name := o.Organization
	if name == "" {
		name = "Kiestoon"
	}
	x.f("fromstring=%s", esc(name))
	if o.MailCmd != "" {
		x.f("mailcmd=%s", esc(o.MailCmd))
	}
	x.f("emaildateformat=%%d-%%m-%%Y %%H:%%M")
	x.f("emailsubject=%s", esc(text[0]))
	x.f("emailbody=%s", esc(text[1]))
	x.nl()
	x.f("[zonemessages]")
	x.f("kiestoon=%s|'vm-received' Q 'digits/at' HM", esc(s.Settings.Timezone))
	x.nl()
	x.f("[default]")
	for _, e := range s.Extensions {
		if !e.Enabled || !e.Voicemail {
			continue
		}
		email := ""
		if e.VoicemailEmail {
			email = e.Email
		}
		opts := []string{"tz=kiestoon", "attach=yes"}
		if e.VoicemailDelete && email != "" {
			opts = append(opts, "delete=yes")
		}
		x.f("%s => %s,%s,%s,,%s", e.Number, e.VoicemailPIN, esc(strings.ReplaceAll(e.Name, ",", " ")), esc(email), strings.Join(opts, "|"))
	}
	return x.b.String()
}

// ---- dialplan ---------------------------------------------------------------

func genDialplan(s *pbx.Snapshot) string {
	st := s.Settings
	var x w
	x.b.WriteString(header)
	trunks := map[int64]pbx.Trunk{}
	enabled := []pbx.Trunk{}
	for _, t := range s.Trunks {
		trunks[t.ID] = t
		if t.Enabled {
			enabled = append(enabled, t)
		}
	}

	// Phones start here. Emergency numbers come first so nothing can shadow them.
	x.f("[kiestoon-internal]")
	x.f("include => kiestoon-emergency")
	x.f("include => kiestoon-features")
	x.f("include => kiestoon-extensions")
	x.f("include => kiestoon-outbound")
	x.f("exten => i,1,Playback(ss-noservice)")
	x.f(" same => n,Hangup()")
	x.nl()

	// 112: always allowed, every trunk in order, emergency caller ID, no channel limits.
	x.f("[kiestoon-emergency]")
	order := []pbx.Trunk{}
	if len(st.EmergencyTrunkIDs) > 0 {
		for _, id := range st.EmergencyTrunkIDs {
			if t, ok := trunks[id]; ok && t.Enabled {
				order = append(order, t)
			}
		}
	} else {
		order = enabled
	}
	for _, num := range pbx.Reserved {
		x.f("exten => %s,1,NoOp(Emergency call from ${CALLERID(num)})", num)
		x.f(" same => n,Set(CDR(kt_emergency)=1)")
		for _, t := range order {
			cid := st.EmergencyCallerID
			if cid == "" {
				cid = t.CallerID
			}
			if cid != "" {
				x.f(" same => n,Set(CALLERID(num)=%s)", cid)
			}
			x.f(" same => n,Dial(PJSIP/112@%s,,T)", t.Endpoint())
			x.f(` same => n,GotoIf($["${DIALSTATUS}" = "ANSWER"]?done)`)
		}
		x.f(" same => n,Playback(ss-noservice)")
		x.f(" same => n(done),Hangup()")
	}
	x.nl()

	x.f("[kiestoon-features]")
	x.f("; *97 own voicemail, *98 any mailbox, *43 echo test")
	x.f("exten => *97,1,Answer()")
	x.f(" same => n,VoiceMailMain(${KT_EXT}@default)")
	x.f(" same => n,Hangup()")
	x.f("exten => *98,1,Answer()")
	x.f(" same => n,VoiceMailMain(@default)")
	x.f(" same => n,Hangup()")
	x.f("exten => *43,1,Answer()")
	x.f(" same => n,Playback(demo-echotest)")
	x.f(" same => n,Echo()")
	x.f(" same => n,Hangup()")
	x.nl()

	x.f("[kiestoon-extensions]")
	for _, e := range s.Extensions {
		if !e.Enabled {
			continue
		}
		x.f("exten => %s,hint,PJSIP/%s", e.Number, e.Number)
		x.f("exten => %s,1,NoOp(Call for %s)", e.Number, e.Number)
		x.f(" same => n,Set(KT_DIAL=${PJSIP_DIAL_CONTACTS(%s)})", e.Number)
		x.f(` same => n,ExecIf($["${KT_DIAL}" = ""]?Set(KT_DIAL=PJSIP/%s))`, e.Number)
		x.f(" same => n,Dial(${KT_DIAL},%d,tT)", e.RingSeconds)
		if e.Voicemail {
			x.f(` same => n,VoiceMail(%s@default,${IF($["${DIALSTATUS}" = "BUSY"]?b:u)})`, e.Number)
		} else {
			x.f(` same => n,ExecIf($["${DIALSTATUS}" = "BUSY"]?Busy(10))`)
			x.f(" same => n,Playback(vm-nobodyavail)")
		}
		x.f(" same => n,Hangup()")
	}
	x.nl()

	// Outbound: one context per route, included in the order of the routes, so the first
	// matching route wins regardless of how specific its pattern is.
	x.f("[kiestoon-outbound]")
	for _, r := range s.Outbound {
		if r.Enabled {
			x.f("include => kiestoon-out-%d", r.ID)
		}
	}
	x.nl()
	for _, r := range s.Outbound {
		if !r.Enabled {
			continue
		}
		x.f("[kiestoon-out-%d]", r.ID)
		x.f("; %s", esc(r.Name))
		seen := map[string]bool{}
		for _, p := range r.Patterns {
			ext := p.Prefix + p.Match
			if seen[ext] {
				continue
			}
			seen[ext] = true
			pat := ext
			if strings.ContainsAny(ext, "XZN.![") {
				pat = "_" + ext
			}
			x.f("exten => %s,1,Set(KT_NUM=%s${EXTEN:%d})", pat, p.Prepend, len(p.Prefix))
			x.f(" same => n,Goto(kiestoon-route-%d,s,1)", r.ID)
		}
		x.nl()
		x.f("[kiestoon-route-%d]", r.ID)
		x.f("exten => s,1,NoOp(Outbound route %d to ${KT_NUM})", r.ID)
		attempt := 0
		for _, tid := range r.TrunkIDs {
			t, ok := trunks[tid]
			if !ok || !t.Enabled {
				continue
			}
			attempt++
			label := fmt.Sprintf("next%d", attempt)
			cid := r.CallerID
			if cid == "" {
				cid = t.CallerID
			}
			if cid != "" {
				x.f(` same => n,Set(CALLERID(num)=${IF($["${KT_OUTCID}" != ""]?${KT_OUTCID}:%s)})`, cid)
			} else {
				x.f(` same => n,ExecIf($["${KT_OUTCID}" != ""]?Set(CALLERID(num)=${KT_OUTCID}))`)
			}
			if t.MaxChannels > 0 {
				x.f(` same => n,GotoIf($[${GROUP_COUNT(%s@kt_trunks)} >= %d]?%s)`, t.Endpoint(), t.MaxChannels, label)
				x.f(" same => n,Set(GROUP(kt_trunks)=%s)", t.Endpoint())
			}
			x.f(" same => n,Set(CDR(kt_trunk)=%s)", esc(t.Name))
			x.f(" same => n,Dial(PJSIP/${KT_NUM}@%s,,T)", t.Endpoint())
			x.f(` same => n,GotoIf($["${DIALSTATUS}" = "BUSY" | "${DIALSTATUS}" = "NOANSWER" | "${DIALSTATUS}" = "ANSWER" | "${DIALSTATUS}" = "CANCEL"]?done)`)
			x.f(" same => n(%s),NoOp(Trying the next trunk)", label)
		}
		x.f(" same => n,Playback(all-circuits-busy-now)")
		x.f(" same => n(done),Hangup()")
		x.nl()
	}

	// Calls from trunks: find the number that was called and send it to its inbound route.
	x.f("[kiestoon-from-trunk]")
	for _, p := range []string{"s", "_X.", "_+X.", "_[a-zA-Z].", "_*."} {
		x.f("exten => %s,1,Set(KT_DID=${IF($[\"${KT_DIDSRC}\" = \"to\"]?${CUT(CUT(PJSIP_HEADER(read,To),@,1),:,2)}:${EXTEN})})", p)
		x.f(` same => n,Set(KT_DID=${FILTER(0-9+,${KT_DID})})`)
		if st.NationalCallerID {
			cc := st.CountryCode
			x.f(` same => n,ExecIf($["${CALLERID(num):0:%d}" = "+%s"]?Set(CALLERID(num)=0${CALLERID(num):%d}))`, len(cc)+1, cc, len(cc)+1)
			x.f(` same => n,ExecIf($["${CALLERID(num):0:%d}" = "00%s"]?Set(CALLERID(num)=0${CALLERID(num):%d}))`, len(cc)+2, cc, len(cc)+2)
			x.f(` same => n,ExecIf($["${CALLERID(num):0:1}" = "+"]?Set(CALLERID(num)=00${CALLERID(num):1}))`)
		}
		x.f(" same => n,Goto(kiestoon-did,${KT_DID},1)")
	}
	x.nl()

	x.f("[kiestoon-did]")
	var catchAll *pbx.InboundRoute
	done := map[string]bool{}
	for i, r := range s.Inbound {
		if !r.Enabled {
			continue
		}
		if r.DID == "" {
			catchAll = &s.Inbound[i]
			continue
		}
		for _, v := range pbx.DIDVariants(r.DID, st.CountryCode) {
			if done[v] {
				continue
			}
			done[v] = true
			x.f("exten => %s,1,Goto(kiestoon-in-%d,s,1)", v, r.ID)
		}
	}
	for _, p := range []string{"_X.", "_+X.", "i"} {
		if catchAll != nil {
			x.f("exten => %s,1,Goto(kiestoon-in-%d,s,1)", p, catchAll.ID)
		} else {
			x.f("exten => %s,1,NoOp(No inbound route for ${EXTEN})", p)
			x.f(" same => n,Playback(ss-noservice)")
			x.f(" same => n,Hangup()")
		}
	}
	x.nl()

	for _, r := range s.Inbound {
		if !r.Enabled {
			continue
		}
		x.f("[kiestoon-in-%d]", r.ID)
		x.f("exten => s,1,NoOp(Inbound route %s)", esc(r.Name))
		if r.CIDPrefix != "" {
			x.f(" same => n,Set(CALLERID(name)=%s${CALLERID(name)})", esc(r.CIDPrefix))
		}
		switch r.DestinationType {
		case "extension":
			x.f(" same => n,Goto(kiestoon-extensions,%s,1)", r.Destination)
		case "voicemail":
			x.f(" same => n,Answer()")
			x.f(" same => n,VoiceMail(%s@default,u)", r.Destination)
			x.f(" same => n,Hangup()")
		default:
			x.f(" same => n,Hangup()")
		}
		x.nl()
	}
	return x.b.String()
}

// ChangedModules returns the Asterisk reload commands needed for the files that changed.
func ChangedModules(changed []string) []string {
	cmds := map[string]bool{}
	for _, f := range changed {
		switch f {
		case "pjsip.conf":
			cmds["module reload res_pjsip.so"] = true
		case "extensions.conf":
			cmds["dialplan reload"] = true
		case "voicemail.conf":
			cmds["module reload app_voicemail.so"] = true
		case "manager_users.conf":
			cmds["manager reload"] = true
		case "rtp.conf":
			cmds["module reload res_rtp_asterisk.so"] = true
		}
	}
	out := make([]string, 0, len(cmds))
	for c := range cmds {
		out = append(out, c)
	}
	sort.Strings(out)
	return out
}
